import { EventEmitter } from "node:events";
import type { FastifyBaseLogger } from "fastify";
import puppeteer, { type Browser } from "puppeteer-core";
import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";

import type { BrowserLauncherOptions } from "../../types/browser.js";
import { getExtensionPaths } from "../../utils/extensions.js";
import { CDPService } from "./cdp.service.js";
import { ShutdownReason } from "./plugins/core/base-plugin.js";

vi.mock("puppeteer-core", async (importOriginal) => {
  const actual = await importOriginal<typeof import("puppeteer-core")>();
  return { ...actual, default: { launch: vi.fn() } };
});

vi.mock("../file.service.js", () => ({
  FileService: {
    getInstance: () => ({
      cleanupFiles: vi.fn().mockResolvedValue(undefined),
      getBaseFilesPath: () => "/fixture/downloads",
    }),
  },
}));

vi.mock("../timezone-fetcher.service.js", () => ({
  TimezoneFetcher: class {
    getTimezone() {
      return Promise.resolve("UTC");
    }
  },
}));

vi.mock("../../utils/extensions.js", () => ({
  getExtensionPaths: vi.fn().mockResolvedValue([]),
}));

vi.mock("./instrumentation/target-manager.js", () => ({
  TargetInstrumentationManager: class {
    attach = vi.fn().mockResolvedValue(undefined);
    detach = vi.fn();
  },
}));

const logger = {
  child: () => logger,
  debug: vi.fn(),
  error: vi.fn(),
  info: vi.fn(),
  warn: vi.fn(),
};

function sessionConfig(id: string, fixtureTag: string): BrowserLauncherOptions {
  return {
    options: { headless: false },
    userDataDir: "/fixture/browser-data",
    userAgent: "FixtureBrowser/1.0",
    skipFingerprintInjection: true,
    extra: { session: { id }, fixtureTag },
  };
}

function fakeBrowser(): Browser {
  const cdp = { send: vi.fn().mockResolvedValue({}), detach: vi.fn().mockResolvedValue(undefined) };
  const target = {
    type: () => "browser",
    createCDPSession: vi.fn().mockResolvedValue(cdp),
  };
  const page = { target: () => target, close: vi.fn().mockResolvedValue(undefined) };
  return Object.assign(new EventEmitter(), {
    close: vi.fn().mockResolvedValue(undefined),
    process: () => ({ kill: vi.fn() }),
    pages: vi.fn().mockResolvedValue([page]),
    newPage: vi.fn().mockResolvedValue(page),
    target: () => target,
    targets: () => [],
    wsEndpoint: () => "ws://fixture/browser",
  }) as unknown as Browser;
}

function lifecycleFixture() {
  const service = new CDPService({}, logger as unknown as FastifyBaseLogger);
  vi.spyOn(service, "getBrowserState").mockResolvedValue({});
  const events: Array<{
    phase: "launch" | "shutdown";
    config: BrowserLauncherOptions | null;
  }> = [];

  // Hook metadata is opaque to CDPService. Exercise the real lifecycle with
  // a mocked browser, without modelling any particular hook implementation.
  service.registerLaunchHook((config) => {
    events.push({ phase: "launch", config });
  });
  service.registerShutdownHook((config) => {
    events.push({ phase: "shutdown", config });
  });

  return { service, events };
}

describe("CDPService lifecycle hook ownership", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.mocked(puppeteer.launch).mockImplementation(async () => fakeBrowser());
    vi.mocked(getExtensionPaths).mockResolvedValue([]);
  });

  afterEach(() => {
    vi.clearAllTimers();
    vi.useRealTimers();
    vi.restoreAllMocks();
    vi.clearAllMocks();
  });

  test("tears down the idle browser before running incoming launch hooks", async () => {
    const { service, events } = lifecycleFixture();
    await service.launch();
    const idleConfig = service.getLaunchConfig();
    const incoming = sessionConfig("incoming", "incoming-metadata");
    events.length = 0;

    await service.startNewSession(incoming);

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch"]);
    expect(events[0].config?.extra).toEqual(idleConfig?.extra);
    expect(events[1].config).toBe(incoming);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("passes outgoing metadata to shutdown hooks during relaunch", async () => {
    const { service, events } = lifecycleFixture();
    const outgoing = sessionConfig("outgoing", "outgoing-metadata");
    const incoming = sessionConfig("incoming", "incoming-metadata");
    await service.startNewSession(outgoing);
    events.length = 0;

    await service.startNewSession(incoming);

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch"]);
    expect(events[0].config?.extra).toBe(outgoing.extra);
    expect(events[1].config).toBe(incoming);
    await service.shutdown(ShutdownReason.SESSION_END);
    expect(events.at(-1)?.config?.extra).toBe(incoming.extra);
  });

  test("updates shutdown ownership when reusing the browser", async () => {
    const { service, events } = lifecycleFixture();
    await service.startNewSession(sessionConfig("first", "shared-metadata"));
    const browser = service.getBrowserInstance();
    const second = sessionConfig("second", "shared-metadata");
    events.length = 0;

    await service.startNewSession(second);

    expect(service.getBrowserInstance()).toBe(browser);
    expect(puppeteer.launch).toHaveBeenCalledOnce();
    expect(events).toEqual([]);
    await service.shutdown(ShutdownReason.SESSION_END);
    expect(events).toEqual([{ phase: "shutdown", config: second }]);
    expect(events[0].config).toBe(second);
  });

  test("retains hook ownership across session end and the next idle-browser relaunch", async () => {
    const { service, events } = lifecycleFixture();
    const first = sessionConfig("first", "first-metadata");
    const second = sessionConfig("second", "second-metadata");
    await service.startNewSession(first);
    events.length = 0;

    await service.endSession();

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch"]);
    expect(events[0].config?.extra).toBe(first.extra);
    expect(events[1].config?.extra).toBeUndefined();
    events.length = 0;

    await service.startNewSession(second);

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch"]);
    expect(events[0].config?.extra).toBeUndefined();
    expect(events[1].config).toBe(second);
    await service.shutdown(ShutdownReason.SESSION_END);
  });

  test("does not pass incoming metadata to cleanup when a launch hook fails", async () => {
    const { service, events } = lifecycleFixture();
    await service.launch();
    const incoming = sessionConfig("incoming", "incoming-metadata");
    events.length = 0;
    service.registerLaunchHook(() => {
      throw new Error("Fixture launch hook failed");
    });
    const launch = service.launch.bind(service);
    vi.spyOn(service, "launch").mockImplementation((config) => launch(config, { maxAttempts: 1 }));

    await expect(service.startNewSession(incoming)).rejects.toThrow("Fixture launch hook failed");

    expect(events.map((event) => event.phase)).toEqual(["shutdown", "launch", "shutdown"]);
    expect(events[0].config?.extra).toBeUndefined();
    expect(events[1].config).toBe(incoming);
    expect(events[2].config).toBeNull();
  });
});

import { describe, expect, test, vi } from "vitest";

import { CDPService } from "./cdp.service.js";

const logger = {
  child: () => logger,
  debug: vi.fn(),
  error: vi.fn(),
  info: vi.fn(),
  warn: vi.fn(),
};

describe("CDPService mobile device emulation", () => {
  test("uses the mobile layout viewport and enables matching touch input", async () => {
    const service = new CDPService({}, logger as any);
    const send = vi.fn().mockResolvedValue({});
    const detach = vi.fn().mockResolvedValue(undefined);
    const page = {
      createCDPSession: vi.fn().mockResolvedValue({ send, detach }),
    };

    Object.assign(service as any, {
      fingerprintData: {
        fingerprint: {
          navigator: {
            userAgent: "Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 Chrome/150 Mobile",
            maxTouchPoints: 10,
          },
          screen: {
            width: 508,
            height: 1074,
            devicePixelRatio: 3,
          },
        },
      },
      currentSessionConfig: {},
    });

    await (service as any).applyDeviceMetricsOverride(page);

    expect(send).toHaveBeenNthCalledWith(1, "Page.setDeviceMetricsOverride", {
      screenWidth: 508,
      screenHeight: 1074,
      width: 508,
      height: 1074,
      mobile: true,
      screenOrientation: { angle: 0, type: "portraitPrimary" },
      deviceScaleFactor: 3,
    });
    expect(send).toHaveBeenNthCalledWith(2, "Emulation.setTouchEmulationEnabled", {
      enabled: true,
      maxTouchPoints: 10,
    });
    expect(detach).toHaveBeenCalledOnce();
  });
});

import { EventEmitter } from "events";
import { TargetType } from "puppeteer-core";
import { describe, expect, it } from "vitest";
import { BrowserEventType } from "../../../types/enums.js";
import type { BrowserLogger } from "./browser-logger.js";
import { attachCDPEvents } from "./cdp-events.js";
import {
  attachBrowserInteractionEvents,
  BROWSER_INTERACTION_BINDING,
  BROWSER_INTERACTION_WORLD,
} from "./browser-interaction-events.js";
import { BROWSER_INTERACTION_SOURCE } from "./browser-interaction-sanitize.js";
import type { BrowserEventUnion } from "./types.js";

class FakeSession extends EventEmitter {
  calls: Array<{ method: string; params?: any }> = [];
  failRunImmediately = false;

  id() {
    return "fake-session";
  }

  async send(method: string, params?: any) {
    this.calls.push({ method, params });
    if (
      this.failRunImmediately &&
      method === "Page.addScriptToEvaluateOnNewDocument" &&
      params?.runImmediately === true
    ) {
      throw new Error("runImmediately not supported");
    }
    return {};
  }
}

class FakePage extends EventEmitter {
  currentUrl = "about:blank";

  url() {
    return this.currentUrl;
  }
}

function createLogger() {
  const records: BrowserEventUnion[] = [];
  const logger: BrowserLogger = {
    record: (event) => records.push(event),
    resetContext: () => {},
    setContext: () => {},
    getContext: () => ({}),
  };
  return { logger, records };
}

describe("browser interaction CDP attachment", () => {
  it("adds the runtime binding and page script", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    const { logger } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );

    expect(session.calls[0]).toEqual({
      method: "Runtime.addBinding",
      params: {
        name: BROWSER_INTERACTION_BINDING,
        executionContextName: BROWSER_INTERACTION_WORLD,
      },
    });
    expect(session.calls[1]).toMatchObject({
      method: "Page.addScriptToEvaluateOnNewDocument",
      params: {
        worldName: BROWSER_INTERACTION_WORLD,
        runImmediately: true,
      },
    });
    expect(session.calls[1].params.source).toContain(BROWSER_INTERACTION_BINDING);
  });

  it("falls back when runImmediately is not supported", async () => {
    const session = new FakeSession();
    session.failRunImmediately = true;
    const page = new FakePage();
    const { logger } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );

    expect(session.calls).toEqual([
      expect.objectContaining({ method: "Runtime.addBinding" }),
      expect.objectContaining({
        method: "Page.addScriptToEvaluateOnNewDocument",
        params: expect.objectContaining({ runImmediately: true }),
      }),
      expect.objectContaining({
        method: "Page.addScriptToEvaluateOnNewDocument",
        params: expect.not.objectContaining({ runImmediately: true }),
      }),
    ]);
  });

  it("records sanitized binding payloads as browser interactions", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    const { logger, records } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );
    records.length = 0;

    session.emit("Runtime.bindingCalled", {
      name: BROWSER_INTERACTION_BINDING,
      payload: JSON.stringify({
        source: BROWSER_INTERACTION_SOURCE,
        timestamp: "2026-05-22T00:00:00.000Z",
        interaction: {
          action: "click",
          eventType: "click",
          pointer: { x: 1, y: 2, button: 0, clickCount: 1 },
          page: { url: "https://example.com" },
        },
      }),
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      type: BrowserEventType.BrowserInteraction,
      timestamp: "2026-05-22T00:00:00.000Z",
      pageId: "page-1",
      interaction: {
        action: "click",
        pointer: { x: 1, y: 2, button: 0, clickCount: 1 },
        page: { url: "https://example.com" },
      },
    });
  });

  it("records only main-frame navigation interactions", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    page.currentUrl = "https://initial.example";
    const { logger, records } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );
    records.length = 0;

    page.emit("framenavigated", {
      parentFrame: () => ({}),
      url: () => "https://iframe.example",
    });
    page.emit("framenavigated", {
      parentFrame: () => null,
      url: () => "https://main.example",
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      type: BrowserEventType.BrowserInteraction,
      interaction: {
        action: "navigate",
        navigation: { url: "https://main.example" },
      },
    });
  });

  it("does not duplicate browser interaction binding calls as raw CDP events", () => {
    const session = new FakeSession();
    const { logger, records } = createLogger();

    attachCDPEvents(session as any, logger);
    session.emit("event", {
      method: "Runtime.bindingCalled",
      params: { name: BROWSER_INTERACTION_BINDING },
    });
    session.emit("event", {
      method: "Runtime.bindingCalled",
      params: { name: "otherBinding" },
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      type: BrowserEventType.CDPEvent,
      cdp: { name: "Runtime.bindingCalled", params: { name: "otherBinding" } },
    });
  });
});

import { describe, expect, it } from "vitest";
import {
  MAX_BROWSER_INTERACTION_TEXT_LENGTH,
  sanitizeInteractionPayload,
  truncateBrowserInteractionText,
} from "./browser-interaction-sanitize.js";

describe("browser interaction sanitizer", () => {
  it("drops malformed and unknown interaction payloads", () => {
    expect(sanitizeInteractionPayload(null)).toBeNull();
    expect(sanitizeInteractionPayload({ interaction: null })).toBeNull();
    expect(
      sanitizeInteractionPayload({
        interaction: { action: "hover", eventType: "mouseover" },
      }),
    ).toBeNull();
    expect(
      sanitizeInteractionPayload({
        interaction: { action: "click", eventType: 123 },
      }),
    ).toBeNull();
  });

  it("normalizes and truncates text fields", () => {
    const longText = "x".repeat(MAX_BROWSER_INTERACTION_TEXT_LENGTH + 20);
    const interaction = sanitizeInteractionPayload({
      interaction: {
        action: "click",
        eventType: "click",
        target: {
          accessibleName: `  ${longText}\n\n`,
          text: "  primary   button  ",
        },
      },
    });

    expect(interaction?.target?.accessibleName).toHaveLength(MAX_BROWSER_INTERACTION_TEXT_LENGTH);
    expect(interaction?.target?.accessibleName?.endsWith("...")).toBe(true);
    expect(interaction?.target?.text).toBe("primary button");
  });

  it("keeps only finite numeric pointer values", () => {
    const interaction = sanitizeInteractionPayload({
      interaction: {
        action: "click",
        eventType: "click",
        pointer: {
          x: 12,
          y: Number.NaN,
          button: Number.POSITIVE_INFINITY,
          clickCount: 1,
        },
      },
    });

    expect(interaction?.pointer).toBeUndefined();
  });

  it("preserves drag pointer shape and drag end metadata", () => {
    const interaction = sanitizeInteractionPayload({
      interaction: {
        action: "drag",
        eventType: "drag",
        endTimestamp: "2026-05-22T00:00:01.000Z",
        pointer: {
          startX: 1,
          startY: 2,
          endX: 10,
          endY: 20,
          button: 0,
        },
        endTarget: { tagName: "button" },
      },
    });

    expect(interaction?.pointer).toEqual({
      startX: 1,
      startY: 2,
      endX: 10,
      endY: 20,
      button: 0,
    });
    expect(interaction?.endTimestamp).toBe("2026-05-22T00:00:01.000Z");
    expect(interaction?.endTarget?.tagName).toBe("button");
  });

  it("sanitizes value and page metadata", () => {
    const interaction = sanitizeInteractionPayload({
      interaction: {
        action: "input",
        eventType: "input",
        value: {
          inputType: "text",
          valueLength: 8,
          text: " hello ",
          redacted: false,
          checked: true,
        },
        page: {
          url: " https://example.com/form ",
          title: 123,
        },
      },
    });

    expect(interaction?.value).toEqual({
      inputType: "text",
      valueLength: 8,
      text: "hello",
      redacted: undefined,
      checked: true,
    });
    expect(interaction?.page).toEqual({
      url: "https://example.com/form",
      title: undefined,
    });
  });

  it("exposes text truncation for direct unit coverage", () => {
    expect(truncateBrowserInteractionText("  a\n b\t c  ")).toBe("a b c");
    expect(truncateBrowserInteractionText("   ")).toBeUndefined();
    expect(truncateBrowserInteractionText(1)).toBeUndefined();
  });
});

import { JSDOM } from "jsdom";
import { afterEach, describe, expect, it, vi } from "vitest";
import { BROWSER_INTERACTION_BINDING } from "./browser-interaction-events.js";
import { createBrowserInteractionScript } from "./browser-interaction-script.js";
import { BROWSER_INTERACTION_SOURCE } from "./browser-interaction-sanitize.js";

function createDom(html: string) {
  const dom = new JSDOM(html, {
    url: "https://example.com/form",
    runScripts: "outside-only",
    pretendToBeVisual: true,
  });
  const binding = vi.fn();
  (dom.window as any)[BROWSER_INTERACTION_BINDING] = binding;
  dom.window.eval(createBrowserInteractionScript(BROWSER_INTERACTION_BINDING));
  return { dom, binding };
}

function payloads(binding: ReturnType<typeof vi.fn>) {
  return binding.mock.calls.map(([payload]) => JSON.parse(payload as string));
}

afterEach(() => {
  vi.restoreAllMocks();
});

describe("browser interaction injected script", () => {
  it("emits click and doubleClick payloads through the binding", () => {
    const { dom, binding } = createDom(`<button id="save">Save</button>`);
    const button = dom.window.document.querySelector("button")!;

    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        clientX: 10,
        clientY: 20,
        detail: 1,
        button: 0,
      }),
    );
    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        clientX: 11,
        clientY: 21,
        detail: 2,
        button: 0,
      }),
    );

    expect(payloads(binding).map((payload) => payload.interaction.action)).toEqual([
      "click",
      "doubleClick",
    ]);
    expect(payloads(binding)[0]).toMatchObject({
      source: BROWSER_INTERACTION_SOURCE,
      interaction: {
        pointer: { x: 10, y: 20, button: 0, clickCount: 1 },
        target: {
          tagName: "button",
          role: "button",
          text: "Save",
        },
      },
    });
    dom.window.close();
  });

  it("omits input text by default while preserving length and redaction metadata", () => {
    const { dom, binding } = createDom(`
      <input id="email" name="email" />
      <input id="password" type="password" />
      <input id="otp" autocomplete="one-time-code" />
    `);
    const email = dom.window.document.querySelector<HTMLInputElement>("#email")!;
    const password = <REDACTED>"#password")!;
    const otp = dom.window.document.querySelector<HTMLInputElement>("#otp")!;

    email.value = "user@example.com";
    password.value = "super-secret";
    otp.value = "123456";

    email.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));
    password.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));
    otp.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions[0].value).toMatchObject({
      inputType: "text",
      valueLength: "user@example.com".length,
    });
    expect(interactions[0].value.text).toBeUndefined();
    expect(interactions[1].value).toMatchObject({
      inputType: "password",
      valueLength: "super-secret".length,
      redacted: true,
    });
    expect(interactions[1].value.text).toBeUndefined();
    expect(interactions[2].value).toMatchObject({
      inputType: "text",
      valueLength: "123456".length,
      redacted: true,
    });
    expect(interactions[2].value.text).toBeUndefined();
    dom.window.close();
  });

  it("redacts sensitive inputs identified by test attributes", () => {
    const { dom, binding } = createDom(`
      <input data-test="credit-card-number" />
      <input data-cy="password" />
    `);
    const creditCard = dom.window.document.querySelector<HTMLInputElement>("[data-test]")!;
    const password = <REDACTED>"[data-cy]")!;

    creditCard.value = "4111111111111111";
    password.value = "secret-from-data-cy";

    creditCard.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));
    password.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions[0].value).toMatchObject({
      valueLength: "4111111111111111".length,
      redacted: true,
    });
    expect(interactions[0].value.text).toBeUndefined();
    expect(interactions[1].value).toMatchObject({
      valueLength: "secret-from-data-cy".length,
      redacted: true,
    });
    expect(interactions[1].value.text).toBeUndefined();
    dom.window.close();
  });

  it("uses the matched test attribute when building selectors", () => {
    const { dom, binding } = createDom(`<button data-cy="save">Save</button>`);
    const button = dom.window.document.querySelector("button")!;

    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        detail: 1,
      }),
    );

    const [payload] = payloads(binding);
    expect(payload.interaction.target.attributes.testId).toBe("save");
    expect(payload.interaction.target.selector.testId).toBe('[data-cy="save"]');
    expect(payload.interaction.target.selector.css).toContain('[data-cy="save"]');
    dom.window.close();
  });

  it("does not include direct text from editable targets", () => {
    const { dom, binding } = createDom(`<div contenteditable="true">typed private note</div>`);
    const editor = dom.window.document.querySelector("div")!;

    editor.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        detail: 1,
      }),
    );

    const [payload] = payloads(binding);
    expect(payload.interaction.target.tagName).toBe("div");
    expect(payload.interaction.target.text).toBeUndefined();
    expect(payload.interaction.target.accessibleName).toBeUndefined();
    dom.window.close();
  });

  it("records non-printable key presses but skips printable input typing", () => {
    const { dom, binding } = createDom(`<input id="query" />`);
    const input = dom.window.document.querySelector<HTMLInputElement>("#query")!;

    input.dispatchEvent(
      new dom.window.KeyboardEvent("keydown", {
        bubbles: true,
        composed: true,
        key: "a",
        code: "KeyA",
      }),
    );
    input.dispatchEvent(
      new dom.window.KeyboardEvent("keydown", {
        bubbles: true,
        composed: true,
        key: "Enter",
        code: "Enter",
      }),
    );

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions).toHaveLength(1);
    expect(interactions[0]).toMatchObject({
      action: "keyPress",
      keyboard: { key: "Enter", code: "Enter" },
    });
    dom.window.close();
  });

  it("emits drag and suppresses the following click", () => {
    const { dom, binding } = createDom(`<button id="drag">Drag</button>`);
    const button = dom.window.document.querySelector("button")!;
    const now = vi.spyOn(dom.window.Date, "now");
    now.mockReturnValueOnce(1_000);
    now.mockReturnValueOnce(1_600);
    now.mockReturnValueOnce(1_601);

    button.dispatchEvent(
      new dom.window.MouseEvent("mousedown", {
        bubbles: true,
        composed: true,
        clientX: 0,
        clientY: 0,
        button: 0,
      }),
    );
    button.dispatchEvent(
      new dom.window.MouseEvent("mouseup", {
        bubbles: true,
        composed: true,
        clientX: 20,
        clientY: 0,
        button: 0,
      }),
    );
    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        clientX: 20,
        clientY: 0,
        detail: 1,
        button: 0,
      }),
    );

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions).toHaveLength(1);
    expect(interactions[0]).toMatchObject({
      action: "drag",
      pointer: { startX: 0, startY: 0, endX: 20, endY: 0, button: 0 },
    });
    dom.window.close();
  });

  it("debounces scroll events", async () => {
    const { dom, binding } = createDom(`<main>content</main>`);
    Object.defineProperty(dom.window, "scrollX", { value: 12, configurable: true });
    Object.defineProperty(dom.window, "scrollY", { value: 34, configurable: true });

    dom.window.document.dispatchEvent(new dom.window.Event("scroll"));
    dom.window.document.dispatchEvent(new dom.window.Event("scroll"));
    expect(binding).not.toHaveBeenCalled();

    await new Promise((resolve) => dom.window.setTimeout(resolve, 250));

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions).toHaveLength(1);
    expect(interactions[0]).toMatchObject({
      action: "scroll",
      pointer: { x: 12, y: 34 },
    });
    dom.window.close();
  });

  it("captures scrolls from nested scroll containers", async () => {
    const { dom, binding } = createDom(`<main id="scrollable">content</main>`);
    const scrollable = dom.window.document.querySelector("#scrollable")!;

    scrollable.dispatchEvent(new dom.window.Event("scroll"));

    await new Promise((resolve) => dom.window.setTimeout(resolve, 250));

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions).toHaveLength(1);
    expect(interactions[0]).toMatchObject({ action: "scroll" });
    dom.window.close();
  });

  it("does not install duplicate listeners", () => {
    const { dom, binding } = createDom(`<button>Save</button>`);
    const button = dom.window.document.querySelector("button")!;
    dom.window.eval(createBrowserInteractionScript(BROWSER_INTERACTION_BINDING));

    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        detail: 1,
      }),
    );

    expect(payloads(binding)).toHaveLength(1);
    dom.window.close();
  });
});

import { describe, it, expect, vi } from "vitest";
import { createBrowserLogger } from "./browser-logger.js";
import { BrowserEventType } from "../../../types/enums.js";

describe("BrowserLogger", () => {
  it("should merge context into events", () => {
    const mockLog = vi.fn();
    const baseLogger = {
      info: mockLog,
      warn: vi.fn(),
      error: vi.fn(),
      debug: vi.fn(),
      fatal: vi.fn(),
      trace: vi.fn(),
      silent: vi.fn(),
      child: vi.fn(),
      level: "info",
    };

    const logger = createBrowserLogger({
      baseLogger: baseLogger as any,
      initialContext: { sessionId: "test-session", orgId: "test-org" },
    });

    logger.record({
      type: BrowserEventType.Console,
      timestamp: "2025-01-01T00:00:00Z",
      console: { level: "log", text: "test message" },
    });

    expect(mockLog).toHaveBeenCalledWith(
      {
        sessionId: "test-session",
        orgId: "test-org",
        type: BrowserEventType.Console,
        timestamp: "2025-01-01T00:00:00Z",
        console: { level: "log", text: "test message" },
      },
      BrowserEventType.Console,
    );
  });

  it("should allow dynamic context updates", () => {
    const mockLog = vi.fn();
    const baseLogger = {
      info: mockLog,
      warn: vi.fn(),
      error: vi.fn(),
      debug: vi.fn(),
      fatal: vi.fn(),
      trace: vi.fn(),
      silent: vi.fn(),
      child: vi.fn(),
      level: "info",
    };

    const logger = createBrowserLogger({
      baseLogger: baseLogger as any,
      initialContext: { sessionId: "session-1" },
    });

    logger.setContext({ orgId: "org-1" });

    expect(logger.getContext()).toEqual({
      sessionId: "session-1",
      orgId: "org-1",
    });

    logger.record({
      type: BrowserEventType.Navigation,
      timestamp: "2025-01-01T00:00:00Z",
      navigation: { url: "https://example.com" },
    });

    expect(mockLog).toHaveBeenCalledWith(
      expect.objectContaining({
        sessionId: "session-1",
        orgId: "org-1",
        type: BrowserEventType.Navigation,
      }),
      BrowserEventType.Navigation,
    );
  });

  it("should support functional context updates", () => {
    const mockLog = vi.fn();
    const baseLogger = {
      info: mockLog,
      warn: vi.fn(),
      error: vi.fn(),
      debug: vi.fn(),
      fatal: vi.fn(),
      trace: vi.fn(),
      silent: vi.fn(),
      child: vi.fn(),
      level: "info",
    };

    const logger = createBrowserLogger({
      baseLogger: baseLogger as any,
      initialContext: { count: 0 },
    });

    logger.setContext((prev) => ({ count: (prev.count as number) + 1 }));
    expect(logger.getContext()).toEqual({ count: 1 });

    logger.setContext((prev) => ({ count: (prev.count as number) + 1 }));
    expect(logger.getContext()).toEqual({ count: 2 });
  });

  it("should prioritize event fields over context fields", () => {
    const mockLog = vi.fn();
    const baseLogger = {
      info: mockLog,
      warn: vi.fn(),
      error: vi.fn(),
      debug: vi.fn(),
      fatal: vi.fn(),
      trace: vi.fn(),
      silent: vi.fn(),
      child: vi.fn(),
      level: "info",
    };

    const logger = createBrowserLogger({
      baseLogger: baseLogger as any,
      initialContext: { type: "wrong-type", pageId: "context-page" },
    });

    logger.record({
      type: BrowserEventType.Request,
      timestamp: "2025-01-01T00:00:00Z",
      pageId: "event-page",
      request: { method: "GET", url: "https://example.com" },
    });

    expect(mockLog).toHaveBeenCalledWith(
      expect.objectContaining({
        type: BrowserEventType.Request,
        pageId: "event-page",
      }),
      BrowserEventType.Request,
    );
  });
});

import { EventEmitter } from "node:events";
import type { CDPSession, Target } from "puppeteer-core";
import { TargetType } from "puppeteer-core";
import { describe, expect, it, vi } from "vitest";

import { BrowserEventType } from "../../../types/index.js";
import { TargetInstrumentationManager } from "./target-manager.js";

describe("TargetInstrumentationManager", () => {
  it("captures network requests from dedicated worker targets", async () => {
    const session = new EventEmitter() as EventEmitter & {
      send: ReturnType<typeof vi.fn>;
      id: () => string;
    };
    const send = vi.fn().mockResolvedValue({});
    session.send = send;
    session.id = () => "cdp-session";

    const target = {
      _targetId: "worker-target",
      _getTargetInfo: () => ({ type: "worker" }),
      url: () => "blob:https://example.com/worker",
      createCDPSession: vi.fn().mockResolvedValue(session as unknown as CDPSession),
    } as unknown as Target;
    const logger = {
      record: vi.fn(),
      resetContext: vi.fn(),
      setContext: vi.fn(),
      getContext: vi.fn().mockReturnValue({}),
    };
    const appLogger = { error: vi.fn(), warn: vi.fn() } as any;
    const onTargetSession = vi.fn().mockResolvedValue(undefined);
    const manager = new TargetInstrumentationManager(
      logger,
      appLogger,
      { captureWorkerNetwork: true },
      onTargetSession,
    );

    await manager.attach(target, TargetType.OTHER);

    expect(send).toHaveBeenCalledWith("Network.enable");
    expect(appLogger.warn).toHaveBeenCalledWith(
      "[TargetManager] Puppeteer's paused dedicated-worker session was unavailable; falling back to createCDPSession(), which may miss initial worker activity",
    );
    expect(onTargetSession).toHaveBeenCalledWith(
      expect.objectContaining({
        target,
        session,
        isDedicatedWorker: true,
        isPuppeteerPaused: false,
      }),
    );

    session.emit("Network.requestWillBeSent", {
      requestId: "request-1",
      request: {
        method: "POST",
        url: "https://example.com/worker-request",
        headers: {},
      },
      type: "Fetch",
    });

    expect(logger.record).toHaveBeenCalledWith(
      expect.objectContaining({
        type: BrowserEventType.Request,
        pageId: "worker-target",
        targetType: TargetType.OTHER,
        request: expect.objectContaining({
          method: "POST",
          url: "https://example.com/worker-request",
        }),
      }),
    );
  });

  it("enables network on Puppeteer's paused worker session", async () => {
    const session = new EventEmitter() as EventEmitter & {
      send: ReturnType<typeof vi.fn>;
      id: () => string;
    };
    const send = vi.fn().mockResolvedValue({});
    session.send = send;
    session.id = () => "cdp-session";

    const target = {
      _targetId: "worker-target",
      _getTargetInfo: () => ({ type: "worker" }),
      _session: () => session,
      url: () => "blob:https://example.com/worker",
      createCDPSession: vi.fn().mockRejectedValue(new Error("must reuse paused session")),
    } as unknown as Target;
    const logger = {
      record: vi.fn(),
      resetContext: vi.fn(),
      setContext: vi.fn(),
      getContext: vi.fn().mockReturnValue({}),
    };
    const onTargetSession = vi.fn().mockResolvedValue(undefined);
    const manager = new TargetInstrumentationManager(
      logger,
      { error: vi.fn() } as any,
      {
        captureWorkerNetwork: true,
      },
      onTargetSession,
    );

    await manager.attach(target, TargetType.OTHER);

    expect(target.createCDPSession).not.toHaveBeenCalled();
    expect(onTargetSession).toHaveBeenCalledWith(
      expect.objectContaining({
        target,
        session,
        isDedicatedWorker: true,
        isPuppeteerPaused: true,
      }),
    );
    expect(send.mock.calls[0]?.[0]).toBe("Network.enable");
  });

  it("queues network capture before a target-session hook resolves", async () => {
    const session = new EventEmitter() as EventEmitter & {
      send: ReturnType<typeof vi.fn>;
      id: () => string;
    };
    const send = vi.fn().mockResolvedValue({});
    session.send = send;
    session.id = () => "cdp-session";

    const target = {
      _targetId: "worker-target",
      _getTargetInfo: () => ({ type: "worker" }),
      _session: () => session,
      url: () => "blob:https://example.com/worker",
      createCDPSession: vi.fn(),
    } as unknown as Target;
    const logger = {
      record: vi.fn(),
      resetContext: vi.fn(),
      setContext: vi.fn(),
      getContext: vi.fn().mockReturnValue({}),
    };
    let resolveTargetSession!: () => void;
    const onTargetSession = vi.fn(
      () => new Promise<void>((resolve) => (resolveTargetSession = resolve)),
    );
    const manager = new TargetInstrumentationManager(
      logger,
      { error: vi.fn() } as any,
      { captureWorkerNetwork: true },
      onTargetSession,
    );

    const attachment = manager.attach(target, TargetType.OTHER);

    expect(onTargetSession).toHaveBeenCalledOnce();
    expect(send.mock.calls.some(([method]) => method === "Network.enable")).toBe(true);

    resolveTargetSession();
    await attachment;
  });
});

import { describe, it, expect } from "vitest";
import { isSimilarConfig } from "./validation.js";
import type { BrowserLauncherOptions } from "../../../types/browser.js";

// Minimal valid config — only required field is `options`
const base: BrowserLauncherOptions = { options: {} };

const withCerts = (certs: string[]): BrowserLauncherOptions => ({
  ...base,
  caCertificates: certs,
});

describe("isSimilarConfig", () => {
  describe("missing configs", () => {
    it("returns false when both configs are undefined", async () => {
      expect(await isSimilarConfig(undefined, undefined)).toBe(false);
    });

    it("returns false when current is undefined", async () => {
      expect(await isSimilarConfig(undefined, base)).toBe(false);
    });

    it("returns false when next is undefined", async () => {
      expect(await isSimilarConfig(base, undefined)).toBe(false);
    });
  });

  describe("caCertificates", () => {
    const certA = "-----BEGIN CERTIFICATE-----\nMIIBcert-a\n-----END CERTIFICATE-----";
    const certB = "-----BEGIN CERTIFICATE-----\nMIIBcert-b\n-----END CERTIFICATE-----";

    it("treats both undefined as similar", async () => {
      expect(await isSimilarConfig(base, base)).toBe(true);
    });

    it("treats both empty arrays as similar", async () => {
      expect(await isSimilarConfig(withCerts([]), withCerts([]))).toBe(true);
    });

    it("treats undefined and empty array as similar", async () => {
      expect(await isSimilarConfig(base, withCerts([]))).toBe(true);
      expect(await isSimilarConfig(withCerts([]), base)).toBe(true);
    });

    it("treats identical cert arrays as similar", async () => {
      expect(await isSimilarConfig(withCerts([certA]), withCerts([certA]))).toBe(true);
    });

    it("treats same certs in different order as similar", async () => {
      expect(await isSimilarConfig(withCerts([certA, certB]), withCerts([certB, certA]))).toBe(
        true,
      );
    });

    it("treats different certs as not similar", async () => {
      expect(await isSimilarConfig(withCerts([certA]), withCerts([certB]))).toBe(false);
    });

    it("treats a cert being added as not similar", async () => {
      expect(await isSimilarConfig(base, withCerts([certA]))).toBe(false);
      expect(await isSimilarConfig(withCerts([certA]), base)).toBe(false);
    });

    it("treats a cert being removed as not similar", async () => {
      expect(await isSimilarConfig(withCerts([certA, certB]), withCerts([certA]))).toBe(false);
    });

    it("treats a subset of certs as not similar", async () => {
      expect(await isSimilarConfig(withCerts([certA]), withCerts([certA, certB]))).toBe(false);
    });
  });

  describe("existing fields are unaffected", () => {
    it("headless mismatch is not similar", async () => {
      const headless: BrowserLauncherOptions = { options: { headless: true } };
      const headful: BrowserLauncherOptions = { options: { headless: false } };
      expect(await isSimilarConfig(headless, headful)).toBe(false);
    });

    it("proxy mismatch is not similar", async () => {
      const a: BrowserLauncherOptions = { options: { proxyUrl: "http://proxy-a:3128" } };
      const b: BrowserLauncherOptions = { options: { proxyUrl: "http://proxy-b:3128" } };
      expect(await isSimilarConfig(a, b)).toBe(false);
    });

    it("userAgent mismatch is not similar", async () => {
      const a: BrowserLauncherOptions = { ...base, userAgent: "Mozilla/5.0 (agent-a)" };
      const b: BrowserLauncherOptions = { ...base, userAgent: "Mozilla/5.0 (agent-b)" };
      expect(await isSimilarConfig(a, b)).toBe(false);
    });

    it("matching full config with caCertificates is similar", async () => {
      const certA = "-----BEGIN CERTIFICATE-----\nMIIBcert-a\n-----END CERTIFICATE-----";
      const config: BrowserLauncherOptions = {
        options: { headless: true, proxyUrl: "http://proxy:3128" },
        userAgent: "Mozilla/5.0",
        blockAds: true,
        caCertificates: [certA],
      };
      expect(await isSimilarConfig(config, { ...config })).toBe(true);
    });
  });
});

import { Database } from "duckdb-async";
import path from "path";
import fs from "fs/promises";
import { LogStorage, LogQuery, LogQueryResult } from "./log-storage.interface.js";
import { BrowserEventUnion } from "../types.js";
import { randomUUID } from "crypto";
import { safeStringify } from "./safe-json.js";

export type ParquetCompression = "zstd" | "snappy" | "gzip" | "none";

export interface DuckDBStorageOptions {
  /**
   * Path to the database file. If not provided, uses in-memory database.
   */
  dbPath?: string;
  /**
   * Maximum number of threads DuckDB can use. Defaults to 2.
   * Set to 1 for minimal CPU impact.
   */
  maxThreads?: number;
  /**
   * Memory limit for DuckDB (e.g., "256MB", "1GB"). Defaults to "256MB".
   */
  memoryLimit?: string;
  /**
   * Parquet compression algorithm. Defaults to "snappy" (fast, lower CPU).
   * - "snappy": Fast compression, moderate size (recommended for CPU efficiency)
   * - "zstd": Best compression ratio, higher CPU
   * - "gzip": Good compression, moderate CPU
   * - "none": No compression, fastest but largest files
   */
  parquetCompression?: ParquetCompression;
  /**
   * Enable automatic write buffering. When enabled, writes are batched
   * and flushed periodically to reduce CPU spikes. Defaults to true.
   */
  enableWriteBuffer?: boolean;
  /**
   * Size of write buffer before auto-flush. Defaults to 100 events.
   */
  writeBufferSize?: number;
  /**
   * Interval in ms to flush write buffer. Defaults to 1000ms.
   */
  writeBufferFlushInterval?: number;
}

/**
 * Maximum number of rows inserted per INSERT statement. A single INSERT that
 * spans the entire write buffer builds a statement with ~7 bound parameters per
 * row; spreading hundreds of thousands of params into `db.run(sql, ...params)`
 * overflows the V8 call stack ("Maximum call stack size exceeded"). Capping the
 * rows per statement keeps each flush bounded regardless of buffer size.
 */
const WRITE_CHUNK_SIZE = 1000;

export class DuckDBStorage implements LogStorage {
  private db: Database | null = null;
  private dbPath: string;
  private maxThreads: number;
  private memoryLimit: string;
  private parquetCompression: ParquetCompression;
  private isInitialized = false;

  // Write buffer for batching
  private writeBuffer: Array<{ event: BrowserEventUnion; context: Record<string, any> }> = [];
  private writeBufferEnabled: boolean;
  private writeBufferSize: number;
  private writeBufferFlushInterval: number;
  private flushTimer: NodeJS.Timeout | null = null;
  private isFlushing = false;

  constructor(options: DuckDBStorageOptions = {}) {
    this.dbPath = options.dbPath || ":memory:";
    this.maxThreads = options.maxThreads ?? 2;
    this.memoryLimit = options.memoryLimit ?? "256MB";
    this.parquetCompression = options.parquetCompression ?? "snappy";
    this.writeBufferEnabled = options.enableWriteBuffer ?? true;
    this.writeBufferSize = options.writeBufferSize ?? 100;
    this.writeBufferFlushInterval = options.writeBufferFlushInterval ?? 1000;
  }

  async initialize(): Promise<void> {
    if (this.isInitialized) return;

    this.db = await Database.create(this.dbPath, {});

    // Throttle CPU usage: limit threads and memory
    await this.db.run(`SET threads = ${this.maxThreads}`);
    await this.db.run(`SET memory_limit = '${this.memoryLimit}'`);

    console.log(`DuckDB initialized: threads=${this.maxThreads}, memory=${this.memoryLimit}`);

    await this.db.run(`
      CREATE TABLE IF NOT EXISTS browser_events (
        id VARCHAR PRIMARY KEY,
        timestamp TIMESTAMP NOT NULL,
        event_type VARCHAR NOT NULL,
        target_type VARCHAR,
        page_id VARCHAR,
        data JSON NOT NULL,
        context JSON NOT NULL,
        indexed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);

    console.log("Created browser_events table");

    await this.db.run(`
      CREATE INDEX IF NOT EXISTS idx_timestamp ON browser_events(timestamp);
    `);
    await this.db.run(`
      CREATE INDEX IF NOT EXISTS idx_event_type ON browser_events(event_type);
    `);
    await this.db.run(`
      CREATE INDEX IF NOT EXISTS idx_page_id ON browser_events(page_id);
    `);

    // Start periodic flush timer if write buffering is enabled
    if (this.writeBufferEnabled) {
      this.startFlushTimer();
    }

    this.isInitialized = true;
  }

  private startFlushTimer(): void {
    if (this.flushTimer) return;
    this.flushTimer = setInterval(() => {
      this.flushWriteBuffer().catch((err) => {
        console.error("DuckDB flush error:", err);
      });
    }, this.writeBufferFlushInterval);
    // Don't block process exit
    this.flushTimer.unref();
  }

  private stopFlushTimer(): void {
    if (this.flushTimer) {
      clearInterval(this.flushTimer);
      this.flushTimer = null;
    }
  }

  private async flushWriteBuffer(): Promise<void> {
    if (this.isFlushing || this.writeBuffer.length === 0 || !this.db) return;

    this.isFlushing = true;
    const toFlush = this.writeBuffer.splice(0, this.writeBuffer.length);

    try {
      await this.writeBatchInternal(toFlush);
    } catch (err) {
      // Put events back on failure (at the front). Use concat rather than
      // `unshift(...toFlush)`: spreading a large array as call arguments throws
      // "Maximum call stack size exceeded" once the buffer is big enough, which
      // would mask the original failure and lose the buffered events.
      this.writeBuffer = toFlush.concat(this.writeBuffer);
      throw err;
    } finally {
      this.isFlushing = false;
    }
  }

  async write(event: BrowserEventUnion, context: Record<string, any>): Promise<void> {
    if (!this.db) {
      throw new Error("Database not initialized");
    }

    if (this.writeBufferEnabled) {
      // Add to buffer
      this.writeBuffer.push({ event, context });

      // Flush if buffer is full
      if (this.writeBuffer.length >= this.writeBufferSize) {
        await this.flushWriteBuffer();
      }
      return;
    }

    // Direct write (no buffering)
    await this.writeSingle(event, context);
  }

  private async writeSingle(event: BrowserEventUnion, context: Record<string, any>): Promise<void> {
    if (!this.db) return;

    const stmt = await this.db.prepare(`
        INSERT INTO browser_events (id, timestamp, event_type, target_type, page_id, data, context, indexed_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
      `);

    const id = randomUUID();
    const timestamp = event.timestamp;
    const eventType = event.type;
    const targetType = event.targetType || null;
    const pageId = event.pageId || null;
    const data = safeStringify(event);
    const contextJson = safeStringify(context);

    await stmt.run(id, timestamp, eventType, targetType, pageId, data, contextJson);
    await stmt.finalize();
  }

  async writeBatch(
    events: Array<{ event: BrowserEventUnion; context: Record<string, any> }>,
  ): Promise<void> {
    if (!this.db) {
      throw new Error("Database not initialized");
    }

    if (events.length === 0) return;

    if (this.writeBufferEnabled) {
      // Add all to buffer
      this.writeBuffer.push(...events);

      // Flush if buffer exceeds threshold
      if (this.writeBuffer.length >= this.writeBufferSize) {
        await this.flushWriteBuffer();
      }
      return;
    }

    // Direct batch write (no buffering)
    await this.writeBatchInternal(events);
  }

  private async writeBatchInternal(
    events: Array<{ event: BrowserEventUnion; context: Record<string, any> }>,
  ): Promise<void> {
    if (!this.db || events.length === 0) return;

    // Insert in fixed-size chunks so a large buffer never produces a single
    // statement with hundreds of thousands of bound parameters (see
    // WRITE_CHUNK_SIZE).
    for (let i = 0; i < events.length; i += WRITE_CHUNK_SIZE) {
      await this.writeChunk(events.slice(i, i + WRITE_CHUNK_SIZE));
    }
  }

  private async writeChunk(
    events: Array<{ event: BrowserEventUnion; context: Record<string, any> }>,
  ): Promise<void> {
    if (!this.db || events.length === 0) return;

    const values: string[] = [];
    const params: any[] = [];

    for (const { event, context } of events) {
      values.push("(?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)");

      const id = randomUUID();
      const timestamp = event.timestamp;
      const eventType = event.type;
      const targetType = event.targetType || null;
      const pageId = event.pageId || null;
      const data = safeStringify(event);
      const contextJson = safeStringify(context);

      params.push(id, timestamp, eventType, targetType, pageId, data, contextJson);
    }

    const sql = `
      INSERT INTO browser_events (id, timestamp, event_type, target_type, page_id, data, context, indexed_at)
      VALUES ${values.join(", ")}
    `;

    await this.db.run(sql, ...params);
  }

  async flush(): Promise<void> {
    // Flush any buffered writes
    await this.flushWriteBuffer();
  }

  async query(query: LogQuery): Promise<LogQueryResult> {
    if (!this.db) {
      throw new Error("Database not initialized");
    }

    const conditions: string[] = [];
    const params: any[] = [];

    if (query.startTime) {
      conditions.push("timestamp >= ?");
      params.push(query.startTime.toISOString());
    }

    if (query.endTime) {
      conditions.push("timestamp <= ?");
      params.push(query.endTime.toISOString());
    }

    if (query.eventTypes && query.eventTypes.length > 0) {
      conditions.push(`event_type IN (${query.eventTypes.map(() => "?").join(", ")})`);
      params.push(...query.eventTypes);
    }

    if (query.pageId) {
      conditions.push("page_id = ?");
      params.push(query.pageId);
    }

    if (query.targetType) {
      conditions.push("target_type = ?");
      params.push(query.targetType);
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
    const limit = query.limit || 100;
    const offset = query.offset || 0;

    const countQuery = `SELECT COUNT(*) as total FROM browser_events ${whereClause}`;
    const countResult = await this.db.all(countQuery, ...params);
    // COUNT(*) may come back as a BigInt from DuckDB bindings – coerce safely for JSON
    const total = Number(countResult[0]?.total ?? 0);

    const eventsQuery = `
      SELECT data, context
      FROM browser_events
      ${whereClause}
      ORDER BY timestamp DESC
      LIMIT ? OFFSET ?
    `;
    const rows = await this.db.all(eventsQuery, ...params, limit, offset);

    const events: BrowserEventUnion[] = rows.map((row: any) => {
      const data = JSON.parse(row.data);
      const context = JSON.parse(row.context);
      return { ...data, ...context };
    });

    return {
      events,
      total,
      hasMore: offset + limit < total,
    };
  }

  supportsParquetExport(): boolean {
    return true;
  }

  async exportToParquet(filePath: string, query?: LogQuery): Promise<string> {
    if (!this.db) {
      throw new Error("Database not initialized");
    }

    // Build WHERE clause if query is provided
    let whereClause = "";
    const params: any[] = [];

    if (query) {
      const conditions: string[] = [];

      if (query.startTime) {
        conditions.push("timestamp >= ?");
        params.push(query.startTime.toISOString());
      }

      if (query.endTime) {
        conditions.push("timestamp <= ?");
        params.push(query.endTime.toISOString());
      }

      if (query.eventTypes && query.eventTypes.length > 0) {
        conditions.push(`event_type IN (${query.eventTypes.map(() => "?").join(", ")})`);
        params.push(...query.eventTypes);
      }

      if (query.pageId) {
        conditions.push("page_id = ?");
        params.push(query.pageId);
      }

      if (query.targetType) {
        conditions.push("target_type = ?");
        params.push(query.targetType);
      }

      whereClause = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
    }

    // Ensure output directory exists
    const dir = path.dirname(filePath);
    await fs.mkdir(dir, { recursive: true });

    // Export to Parquet with configurable compression
    const sanitizedPath = filePath.replace(/'/g, "''");
    const compressionClause =
      this.parquetCompression === "none"
        ? ""
        : `, COMPRESSION ${this.parquetCompression.toUpperCase()}`;
    const exportQuery = `
      COPY (
        SELECT * FROM browser_events ${whereClause}
      ) TO '${sanitizedPath}' (FORMAT PARQUET${compressionClause})
    `;

    await this.db.run(exportQuery);

    return filePath;
  }

  async getStats(): Promise<{
    totalEvents: number;
    oldestEvent: Date | null;
    newestEvent: Date | null;
    sizeBytes: number;
  }> {
    if (!this.db) {
      throw new Error("Database not initialized");
    }

    const result = await this.db.all(`
      SELECT
        COUNT(*) as total,
        MIN(timestamp) as oldest,
        MAX(timestamp) as newest
      FROM browser_events
    `);

    const row = result[0];
    let sizeBytes = 0;

    // Get file size if using file-based storage
    if (this.dbPath !== ":memory:") {
      const stats = await fs.stat(this.dbPath);
      sizeBytes = stats.size;
    }

    return {
      totalEvents: Number(row?.total ?? 0),
      oldestEvent: row?.oldest ? new Date(row.oldest) : null,
      newestEvent: row?.newest ? new Date(row.newest) : null,
      sizeBytes,
    };
  }

  async clear(options: { vacuum?: boolean } = {}): Promise<void> {
    if (!this.db) {
      throw new Error("Database not initialized");
    }

    // Flush any pending writes first
    await this.flushWriteBuffer();

    await this.db.run("DELETE FROM browser_events");

    // VACUUM is CPU-intensive; run in background by default
    if (options.vacuum) {
      await this.db.run("VACUUM");
    } else {
      // Fire-and-forget vacuum (don't block)
      this.db.run("VACUUM").catch((err) => {
        console.error("Background VACUUM error:", err);
      });
    }
  }

  /**
   * Run VACUUM manually when CPU is idle. This reclaims disk space
   * and optimizes the database, but is CPU-intensive.
   */
  async vacuum(): Promise<void> {
    if (!this.db) {
      throw new Error("Database not initialized");
    }
    await this.db.run("VACUUM");
  }

  async close(): Promise<void> {
    // Stop the flush timer
    this.stopFlushTimer();

    // Flush any remaining buffered writes
    if (this.writeBuffer.length > 0 && this.db) {
      try {
        await this.flushWriteBuffer();
      } catch (err) {
        console.error("Error flushing buffer on close:", err);
      }
    }

    if (this.db) {
      await this.db.close();
      this.db = null;
    }

    this.isInitialized = false;
  }

  /**
   * Get current buffer stats for monitoring
   */
  getBufferStats(): { bufferedEvents: number; isBufferingEnabled: boolean } {
    return {
      bufferedEvents: this.writeBuffer.length,
      isBufferingEnabled: this.writeBufferEnabled,
    };
  }
}

import { LogStorage, LogQuery, LogQueryResult } from "./log-storage.interface.js";
import { BrowserEventUnion } from "../types.js";

interface StoredEvent {
  event: BrowserEventUnion;
  context: Record<string, any>;
  timestamp: Date;
}

/**
 * Simple in-memory log storage for testing or when persistence is not needed.
 * Note: This implementation does not support Parquet export.
 */
export class InMemoryStorage implements LogStorage {
  private events: StoredEvent[] = [];
  private maxEvents: number;

  constructor(maxEvents: number = 10000) {
    this.maxEvents = maxEvents;
  }

  async initialize(): Promise<void> {
    // No initialization needed
  }

  async write(event: BrowserEventUnion, context: Record<string, any>): Promise<void> {
    this.events.push({
      event,
      context,
      timestamp: new Date(event.timestamp),
    });

    // Trim old events if we exceed the max
    if (this.events.length > this.maxEvents) {
      this.events = this.events.slice(-this.maxEvents);
    }
  }

  async writeBatch(
    events: Array<{ event: BrowserEventUnion; context: Record<string, any> }>,
  ): Promise<void> {
    for (const { event, context } of events) {
      await this.write(event, context);
    }
  }

  async query(query: LogQuery): Promise<LogQueryResult> {
    let filtered = [...this.events];

    // Apply filters
    if (query.startTime) {
      filtered = filtered.filter((e) => e.timestamp >= query.startTime!);
    }

    if (query.endTime) {
      filtered = filtered.filter((e) => e.timestamp <= query.endTime!);
    }

    if (query.eventTypes && query.eventTypes.length > 0) {
      filtered = filtered.filter((e) => query.eventTypes!.includes(e.event.type));
    }

    if (query.pageId) {
      filtered = filtered.filter((e) => e.event.pageId === query.pageId);
    }

    if (query.targetType) {
      filtered = filtered.filter((e) => e.event.targetType === query.targetType);
    }

    // Sort by timestamp descending
    filtered.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

    const total = filtered.length;
    const limit = query.limit || 100;
    const offset = query.offset || 0;

    const events: BrowserEventUnion[] = filtered
      .slice(offset, offset + limit)
      .map((e) => ({ ...e.event, ...e.context }));

    return {
      events,
      total,
      hasMore: offset + limit < total,
    };
  }

  supportsParquetExport(): boolean {
    return false;
  }

  async exportToParquet(filePath: string, query?: LogQuery): Promise<string> {
    throw new Error("Parquet export not supported in InMemoryStorage. Use DuckDBStorage instead.");
  }

  async getStats(): Promise<{
    totalEvents: number;
    oldestEvent: Date | null;
    newestEvent: Date | null;
    sizeBytes: number;
  }> {
    const timestamps = this.events.map((e) => e.timestamp.getTime());

    return {
      totalEvents: this.events.length,
      oldestEvent: timestamps.length > 0 ? new Date(Math.min(...timestamps)) : null,
      newestEvent: timestamps.length > 0 ? new Date(Math.max(...timestamps)) : null,
      sizeBytes: JSON.stringify(this.events).length, // Approximate
    };
  }

  async clear(): Promise<void> {
    this.events = [];
  }

  async flush(): Promise<void> {
    // No-op for in-memory storage
  }

  async close(): Promise<void> {
    this.events = [];
  }
}

