/**
 * A proxy whose byte counters settle when it closes, mirroring proxy-chain: a
 * connection is credited on `connectionClosed`, and a long-lived tunnel stays
 * open until the browser goes away.
 */
function createProxyServer() {
  const proxy: IProxyServer & { close: ReturnType<typeof vi.fn> } = {
    url: "http://127.0.0.1:0",
    upstreamProxyUrl: "",
    txBytes: 1_000,
    rxBytes: 2_000,
    listen: vi.fn().mockResolvedValue(undefined),
    close: vi.fn().mockImplementation(async () => {
      Object.assign(proxy, { txBytes: 3_000, rxBytes: 400_000 });
    }),
  };
  return proxy;
}

function createService({ withProxy = false } = {}) {
  const cdpService = {
    getUserAgent: () => "test-agent",
    getDimensions: () => ({ width: 1920, height: 1080 }),
    endSession: vi.fn().mockResolvedValue(undefined),
  };
  const service = new SessionService({
    cdpService: cdpService as never,
    seleniumService: { close: vi.fn() } as never,
    fileService: {} as never,
    logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn() } as never,
  });

  const proxy = withProxy ? createProxyServer() : undefined;
  if (proxy) service.activeSession.proxyServer = proxy;

  return { service, cdpService, proxy };
}

describe("SessionService.endSession proxy accounting", () => {
  it("reports the counters the proxy settles on close", async () => {
    const { service, proxy } = createService({ withProxy: true });

    const released = await service.endSession();

    expect(proxy!.close).toHaveBeenCalledTimes(1);
    expect(proxy!.close).toHaveBeenCalledWith(true);
    expect(released.proxyRxBytes).toBe(400_000);
    expect(released.proxyTxBytes).toBe(3_000);
  });

  it("closes the proxy only after the browser is torn down", async () => {
    const order: string[] = [];
    const { service, cdpService, proxy } = createService({ withProxy: true });
    cdpService.endSession.mockImplementation(async () => {
      order.push("cdp");
    });
    proxy!.close.mockImplementation(async () => {
      order.push("proxy");
    });

    await service.endSession();

    expect(order).toEqual(["cdp", "proxy"]);
  });

  it("leaves the counters at zero when the session had no proxy", async () => {
    const { service } = createService();

    const released = await service.endSession();

    expect(released.proxyRxBytes).toBe(0);
    expect(released.proxyTxBytes).toBe(0);
  });
});

import fs from "fs/promises";
import path from "path";
import os from "os";
import { Level } from "level";
import iconv from "iconv-lite";
import { copyDirectory } from "../../utils/leveldb.js";

/**
 * Decode a Chrome-encoded string.
 *  - 0x00 prefix => UTF‑16‑LE encoded string
 *  - 0x01 prefix => ISO‑8859‑1 encoded string
 */
function decodeString(raw: Buffer): { value: string; charset: string } {
  if (!raw || raw.length === 0) {
    throw new Error("Cannot decode empty buffer");
  }

  const prefix = raw[0];
  const payload = raw.subarray(1);

  if (prefix === 0) {
    try {
      const decoded = iconv.decode(payload, "utf16-le");
      return { value: decoded, charset: "UTF-16-LE" };
    } catch (err: unknown) {
      throw new Error(`Failed to decode UTF-16-LE: ${err}`);
    }
  } else if (prefix === 1) {
    return { value: payload.toString("latin1"), charset: "ISO-8859-1" };
  }

  throw new Error(`Unknown string encoding prefix: ${prefix}`);
}

export interface StorageMetadata {
  storageKey: string;
  timestamp: Date;
  size: number;
}

export interface LocalStorageRecord {
  storageKey: string;
  scriptKey: string;
  charset: string;
  decoded: string;
  mime?: string;
  conversions?: string[];
  jsonType?: string;
  value?: unknown;
}

export class LocalStoreDb {
  private db: Level<Buffer, Buffer>;
  private tmpDir: string | null;
  public records: LocalStorageRecord[] = [];

  private constructor(db: Level<Buffer, Buffer>, tmpDir: string | null = null) {
    this.db = db;
    this.tmpDir = tmpDir;
  }

  public static async open(dir: string): Promise<LocalStoreDb> {
    try {
      const db = new Level<Buffer, Buffer>(dir, {
        createIfMissing: false,
        keyEncoding: "buffer",
        valueEncoding: "buffer",
      } as any);
      // wait until open
      await db.open();
      return new LocalStoreDb(db);
    } catch (err) {
      const tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), "chrome-leveldb-"));
      try {
        await copyDirectory(dir, tmpDir);
        const db = new Level<Buffer, Buffer>(tmpDir, {
          createIfMissing: false,
          keyEncoding: "buffer",
          valueEncoding: "buffer",
        } as any);
        await db.open();
        return new LocalStoreDb(db, tmpDir);
      } catch (copyErr) {
        await fs.rm(tmpDir, { recursive: true, force: true }).catch(() => {});
        throw copyErr;
      }
    }
  }

  public async load(): Promise<void> {
    const META_PREFIX = Buffer.from("META:");
    const RECORD_PREFIX = Buffer.from("_");

    for await (const [keyBuf, valueBuf] of this.db.iterator() as any) {
      const key: Buffer = keyBuf as Buffer;
      const value: Buffer = valueBuf as Buffer;

      if (key[0] === RECORD_PREFIX[0]) {
        // Remove prefix
        const withoutPrefix = key.subarray(1);
        const nullIndex = withoutPrefix.indexOf(0);
        if (nullIndex === -1) continue;

        const storageKeyBytes = withoutPrefix.subarray(0, nullIndex);
        const scriptKeyBytes = withoutPrefix.subarray(nullIndex + 1);

        const storageKey = storageKeyBytes.toString();
        let scriptKeyDecoded: { value: string; charset: string };
        let valueDecoded: { value: string; charset: string };
        try {
          scriptKeyDecoded = decodeString(scriptKeyBytes);
          valueDecoded = decodeString(valueBuf);
        } catch {
          continue;
        }

        this.records.push({
          storageKey,
          scriptKey: scriptKeyDecoded.value,
          charset: valueDecoded.charset,
          decoded: valueDecoded.value,
        });
      }
    }
  }

  public async close(): Promise<void> {
    // @ts-ignore types mismatch but close exists
    if (this.db.status === "open") await this.db.close().catch(() => {});
    if (this.tmpDir) {
      const tmpDir = this.tmpDir;
      this.tmpDir = null;
      await fs.rm(tmpDir, { recursive: true, force: true }).catch(() => {});
    }
  }
}

export class ChromeLocalStorageReader {
  /**
   * Reads a Chrome Local Storage LevelDB directory and returns a nested record of items
   * grouped by domain / storage key.
   */
  public static async readLocalStorage(
    dir: string,
  ): Promise<Record<string, Record<string, string>>> {
    const ldb = await LocalStoreDb.open(dir);
    try {
      await ldb.load();
      const result: Record<string, Record<string, string>> = {};
      for (const rec of ldb.records) {
        if (!result[rec.storageKey]) {
          result[rec.storageKey] = {};
        }
        result[rec.storageKey][rec.scriptKey] = rec.decoded;
      }
      return result;
    } finally {
      await ldb.close();
    }
  }
}

import fs from "fs/promises";
import path from "path";
import os from "os";
import { Level } from "level";
import iconv from "iconv-lite";
import { fileTypeFromBuffer } from "file-type";
import { copyDirectory } from "../../utils/leveldb.js";

/**
 * Decode a UTF-16LE string
 */
function decodeUTF16LE(raw: Buffer): string {
  try {
    return iconv.decode(raw, "utf16-le");
  } catch (err: unknown) {
    throw new Error(`Failed to decode UTF-16-LE: ${err}`);
  }
}

export interface SessionStorageRecord {
  mapId: number;
  origin: string;
  key: string;
  charset: string;
  decoded: string;
  mime?: string;
  conversions?: string[];
  jsonType?: string;
  value?: unknown;
}

export class SessionStoreDb {
  private db: Level<Buffer, Buffer>;
  public records: SessionStorageRecord[] = [];
  private mapIdToOrigin: Map<number, string> = new Map();

  private tmpDir: string | null;

  private constructor(db: Level<Buffer, Buffer>, tmpDir: string | null = null) {
    this.db = db;
    this.tmpDir = tmpDir;
  }

  public static async open(dir: string): Promise<SessionStoreDb> {
    try {
      const db = new Level<Buffer, Buffer>(dir, {
        createIfMissing: false,
        keyEncoding: "buffer",
        valueEncoding: "buffer",
      } as any);
      // wait until open
      await db.open();
      return new SessionStoreDb(db);
    } catch (err) {
      const tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), "chrome-leveldb-"));
      try {
        await copyDirectory(dir, tmpDir);
        const db = new Level<Buffer, Buffer>(tmpDir, {
          createIfMissing: false,
          keyEncoding: "buffer",
          valueEncoding: "buffer",
        } as any);
        await db.open();
        return new SessionStoreDb(db, tmpDir);
      } catch (copyErr) {
        await fs.rm(tmpDir, { recursive: true, force: true }).catch(() => {});
        throw copyErr;
      }
    }
  }

  /**
   * Load namespace records to map from mapId to origin (hostname)
   */
  private async loadNamespaceRecords(): Promise<void> {
    const NAMESPACE_PREFIX = Buffer.from("namespace-");

    for await (const [keyBuf, valueBuf] of this.db.iterator() as any) {
      const key: Buffer = keyBuf as Buffer;
      const value: Buffer = valueBuf as Buffer;

      if (key.indexOf(NAMESPACE_PREFIX) === 0) {
        const keyStr = key.toString();
        // Format: "namespace-<uuid>-<hostname>"
        const parts = keyStr.split("-");
        if (parts.length < 3) continue;

        // Get hostname from the remaining parts (in case hostname contains dashes)
        const hostname = parts.slice(2).join("-").replace(/\/$/, "");

        // Get map-id value
        const mapId = parseInt(value.toString(), 10);
        if (isNaN(mapId)) continue;

        this.mapIdToOrigin.set(mapId, hostname);
      }
    }
  }

  public async load(): Promise<void> {
    // First load namespace records to build mapId to origin mapping
    await this.loadNamespaceRecords();

    const MAP_PREFIX = Buffer.from("map-");

    for await (const [keyBuf, valueBuf] of this.db.iterator() as any) {
      const key: Buffer = keyBuf as Buffer;
      const value: Buffer = valueBuf as Buffer;

      if (key.indexOf(MAP_PREFIX) === 0) {
        const withoutPrefix = key.subarray(MAP_PREFIX.length);
        const parts = withoutPrefix.toString().split("-", 2);

        if (parts.length !== 2) continue;

        const mapId = parseInt(parts[0], 10);
        if (isNaN(mapId)) continue;

        const keyStr = parts[1];
        let valueDecoded: string;

        try {
          valueDecoded = decodeUTF16LE(value);
        } catch {
          continue;
        }

        // Look up the origin from the mapId
        const origin = this.mapIdToOrigin.get(mapId) || "unknown-origin";

        this.records.push({
          mapId,
          origin,
          key: keyStr,
          charset: "UTF-16-LE",
          decoded: valueDecoded,
        });
      }
    }
  }

  public async close(): Promise<void> {
    // @ts-ignore types mismatch but close exists
    if (this.db.status === "open") await this.db.close().catch(() => {});
    if (this.tmpDir) {
      const tmpDir = this.tmpDir;
      this.tmpDir = null;
      await fs.rm(tmpDir, { recursive: true, force: true }).catch(() => {});
    }
  }
}

/**
 * Process a session storage record to add metadata about its content
 */
export function processSessionRecord(record: SessionStorageRecord): SessionStorageRecord {
  const result = { ...record };
  const buffer = Buffer.from(record.decoded);
  let mime = "application/octet-stream";
  const conversions: string[] = [];
  let jsonType = "";
  let value: unknown = null;

  // Try to parse as JSON
  try {
    value = JSON.parse(record.decoded);
    mime = "application/json";

    if (value === null) {
      jsonType = "null";
    } else if (Array.isArray(value)) {
      jsonType = "array";
    } else if (typeof value === "object") {
      jsonType = "object";
    } else if (typeof value === "string") {
      jsonType = "string";
    } else if (typeof value === "number") {
      jsonType = "number";
    } else if (typeof value === "boolean") {
      jsonType = "boolean";
    }
  } catch {
    // Not valid JSON, try to determine file type
    try {
      const quoted = JSON.stringify(record.decoded);
      if (JSON.parse(quoted)) {
        value = quoted;
        mime = "text/plain";
        conversions.push("JSON.stringify");
      }
    } catch {
      const b64 = buffer.toString("base64");
      value = JSON.stringify(b64);
      conversions.push("buffer.toString('base64')");
      conversions.push("JSON.stringify");

      // Try to detect MIME type
      fileTypeFromBuffer(buffer)
        .then((type) => {
          if (type) {
            result.mime = type.mime;
          }
        })
        .catch(() => {});
    }
  }

  result.mime = mime;
  result.conversions = conversions;
  result.jsonType = jsonType;
  result.value = value;

  return result;
}

export class ChromeSessionStorageReader {
  /**
   * Reads a Chrome Session Storage LevelDB directory and returns a nested record of items
   * grouped by origin (hostname).
   */
  public static async readSessionStorage(
    dir: string,
  ): Promise<Record<string, Record<string, string>>> {
    const sdb = await SessionStoreDb.open(dir);
    try {
      await sdb.load();
      const result: Record<string, Record<string, string>> = {};

      for (const rec of sdb.records) {
        if (!result[rec.origin]) {
          result[rec.origin] = {};
        }
        result[rec.origin][rec.key] = rec.decoded;
      }

      return result;
    } finally {
      await sdb.close();
    }
  }
}

import type { CDPSession } from "puppeteer-core";
import { BrowserEventType } from "../../../types/index.js";
import { BrowserLogger } from "./browser-logger.js";
import { BROWSER_INTERACTION_BINDING } from "./browser-interaction-events.js";

/**
 * Attaches protocol tracing to a CDP session.
 * Logs only protocol commands / notifications so you can diff automation flow between runs.
 */
export function attachCDPEvents(session: CDPSession, logger: BrowserLogger): void {
  const sessionId = session.id?.() ?? "unknown";
  const ts = () => new Date().toISOString();
  const originalSend = session.send.bind(session);
  type Method = Parameters<typeof session.send>[0];

  session.send = async function (method: Method, params?: object) {
    const start = performance.now();

    logger.record({
      type: BrowserEventType.CDPCommand,
      timestamp: ts(),
      cdp: { command: method, params, sessionId },
    });

    try {
      const result = await originalSend(method, params);
      logger.record({
        type: BrowserEventType.CDPCommandResult,
        timestamp: ts(),
        cdp: {
          command: method,
          duration: performance.now() - start,
          sessionId,
          success: true,
        },
      });
      return result;
    } catch (err) {
      logger.record({
        type: BrowserEventType.CDPCommandResult,
        timestamp: ts(),
        cdp: {
          command: method,
          duration: performance.now() - start,
          sessionId,
          success: false,
          error: (err as Error).message,
        },
      });
      throw err;
    }
  } as typeof session.send;

  const ignore = new Set([
    "Runtime.consoleAPICalled",
    "Log.entryAdded",
    // Network events are handled by page-events.ts via typed Request/Response events.
    // Suppress here to avoid duplicate logging.
    "Network.requestWillBeSent",
    "Network.responseReceived",
    "Network.dataReceived",
    "Network.loadingFinished",
    "Network.loadingFailed",
    "Network.requestServedFromCache",
    "Network.requestWillBeSentExtraInfo",
    "Network.responseReceivedExtraInfo",
  ]);
  session.on("event", (event: any) => {
    const { method, params } = event;
    if (ignore.has(method)) return;
    if (method === "Runtime.bindingCalled" && params?.name === BROWSER_INTERACTION_BINDING) return;
    logger.record({
      type: BrowserEventType.CDPEvent,
      timestamp: ts(),
      cdp: { name: method, params },
    });
  });
}

