        expect(mangledLinkCount(markdown)).toBe(0);
        expect(relativeLinkCount(markdown)).toBe(0);

        if (page.expectAuthor) {
          expect(result.author.length).toBeGreaterThan(0);
          expect(result.wordCount).toBeGreaterThan(0);
