import { describe, expect, it } from "vitest";
import { INVARIANTS, runInvariants, type InvariantContext } from "./invariants";

const ctx = (markdown: string, html = "<html><body></body></html>"): InvariantContext => ({
  url: "https://example.com/page",
  html,
  markdown,
});

const fails = (markdown: string, name: string, html?: string): boolean =>
  runInvariants(ctx(markdown, html)).some((r) => r.name === name && !r.pass);

// A clean, realistic markdown blob that should satisfy every invariant.
const CLEAN = [
  "# Title",
  "",
  "Some body text that is clearly long enough to count as real content, with",
  "more than a handful of words so the contentful check is satisfied here.",
  "",
  "See the [docs](https://example.com/docs) and the [api](https://example.com/api).",
  "",
  "![hero](https://example.com/hero.png)",
  "",
  "```python",
  "print('hi')",
  "```",
].join("\n");

const CONTENTFUL_HTML = `<html><body><article>${"word ".repeat(200)}</article></body></html>`;

describe("invariants: clean markdown passes everything", () => {
  it("produces zero failures on a well-formed document", () => {
    const failures = runInvariants(ctx(CLEAN, CONTENTFUL_HTML)).filter((r) => !r.pass);
    expect(failures.map((f) => `${f.name}: ${f.detail}`)).toEqual([]);
  });
});

describe("invariants: each one catches its failure mode", () => {
  it("no-script-style-leak", () => {
    expect(fails("text <script>alert(1)</script> more", "no-script-style-leak")).toBe(true);
    expect(fails("text <style>.a{}</style>", "no-script-style-leak")).toBe(true);
  });

  it("no-relative-links", () => {
    expect(fails("[home](/home)", "no-relative-links")).toBe(true);
    expect(fails("[up](../sibling)", "no-relative-links")).toBe(true);
    expect(fails("[here](./local)", "no-relative-links")).toBe(true);
    // protocol-relative and absolute must NOT trip it
    expect(fails("[cdn](//cdn.example.com/x)", "no-relative-links")).toBe(false);
    expect(fails("[abs](https://example.com/x)", "no-relative-links")).toBe(false);
  });

  it("no-mangled-links", () => {
    expect(fails('[x](https://e.com/a"title)', "no-mangled-links")).toBe(true);
  });

  it("non-empty-when-contentful", () => {
    expect(fails("", "non-empty-when-contentful", CONTENTFUL_HTML)).toBe(true);
    // an empty page must NOT trip it (nothing to extract)
    expect(fails("", "non-empty-when-contentful", "<html><body></body></html>")).toBe(false);
  });

  it("no-secret-leak", () => {
    expect(fails(`token sk-${"a1B2c3D4e5".repeat(3)} here`, "no-secret-leak")).toBe(true);
    expect(fails("AKIAIOSFODNN7EXAMPLE is a key", "no-secret-leak")).toBe(true);
    expect(fails("-----BEGIN PRIVATE KEY-----", "no-secret-leak")).toBe(true);
    expect(fails("the word sketch is fine", "no-secret-leak")).toBe(false);
  });

  it("no-leaked-chrome-tags (warn)", () => {
    expect(fails("<nav>menu</nav>", "no-leaked-chrome-tags")).toBe(true);
    expect(fails("<iframe src=x></iframe>", "no-leaked-chrome-tags")).toBe(true);
  });

  it("no-empty-image-src (warn)", () => {
    expect(fails("![lost]()", "no-empty-image-src")).toBe(true);
    expect(fails("![ok](https://e.com/i.png)", "no-empty-image-src")).toBe(false);
  });

  it("no-empty-or-fragment-links (warn)", () => {
    expect(fails("see [toc](#section)", "no-empty-or-fragment-links")).toBe(true);
    expect(fails("a [x]() b", "no-empty-or-fragment-links")).toBe(true);
  });

  it("balanced-code-fences (warn)", () => {
    expect(fails("```python\nprint(1)", "balanced-code-fences")).toBe(true);
    expect(fails("```python\nprint(1)\n```", "balanced-code-fences")).toBe(false);
  });

  it("no-html-comments (warn)", () => {
    expect(fails("text <!-- tracking --> text", "no-html-comments")).toBe(true);
  });

  it("size-ratio-sane (warn)", () => {
    const tinyHtml = `<html><body>${"w ".repeat(60)}</body></html>`;
    const bloated = "dup ".repeat(300);
    expect(fails(bloated, "size-ratio-sane", tinyHtml)).toBe(true);
  });
});

describe("invariants: severity split is wired", () => {
  it("error subset is a strict subset of all invariants", () => {
    const errors = runInvariants(ctx(CLEAN, CONTENTFUL_HTML), "error");
    expect(errors.length).toBeGreaterThan(0);
    expect(errors.length).toBeLessThan(INVARIANTS.length);
    expect(errors.every((r) => r.severity === "error")).toBe(true);
  });
});

/**
 * Tier 1 eval: label-free invariants.
 *
 * Every check here must hold for the markdown of ANY page, with no ground-truth
 * reference. They catch the failure modes that actually bite a scraping API in
 * production — leaked chrome/scripts, unresolved relative links, empty output on
 * a contentful page, secret leakage, broken structure — without anyone having to
 * hand-label "correct" markdown.
 *
 * Severity:
 *   - "error": hard contract. corpus.test.ts fails CI if any page violates one.
 *   - "warn":  quality signal. surfaced in the report, does not gate CI.
 */

export type Severity = "error" | "warn";

export type InvariantContext = {
  url: string;
  /** HTML fed into the converter. */
  html: string;
  /** contentMarkdown produced by the pipeline. */
  markdown: string;
  /** Optional richer signals from the DefuddleResponse. */
  result?: {
    content?: string;
    wordCount?: number;
    extractorType?: string | null;
    title?: string;
  };
};

export type InvariantResult = {
  name: string;
  severity: Severity;
  pass: boolean;
  /** Human-readable reason; empty when pass. */
  detail: string;
};

type Invariant = {
  name: string;
  severity: Severity;
  check: (ctx: InvariantContext) => { pass: boolean; detail?: string };
};

const words = (s: string): number => s.split(/\s+/).filter(Boolean).length;

/** Rough visible-text estimate of the source HTML (drop script/style, strip tags). */
const visibleText = (html: string): string =>
  html
    .replace(/<script\b[\s\S]*?<\/script\s*>/gi, " ")
    .replace(/<style\b[\s\S]*?<\/style\s*>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const sample = (matches: RegExpMatchArray | null, n = 3): string =>
  (matches ?? []).slice(0, n).join(" , ");

// Patterns for things that should never survive into clean markdown.
const SECRET_PATTERNS: <REDACTED> name: string; re: RegExp }[] = [
  { name: "openai/sk", re: /\bsk-[A-Za-z0-9]{20,}\b/ },
  { name: "aws-akid", re: /\bAKIA[0-9A-Z]{16}\b/ },
  { name: "github", re: /\bgh[pousr]_[A-Za-z0-9]{20,}\b/ },
  { name: "slack", re: /\bxox[baprs]-[A-Za-z0-9-]{10,}\b/ },
  { name: "jwt", re: /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/ },
  { name: "private-key", re: /-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----/ },
];

/** Word count below which a page is "not contentful" and we assert nothing. */
const CONTENTFUL_HTML_WORDS = 50;
/** Minimum markdown words expected when the source clearly had content. */
const MIN_MARKDOWN_WORDS = 10;

export const INVARIANTS: Invariant[] = [
  {
    name: "no-script-style-leak",
    severity: "error",
    check: ({ markdown }) => {
      const m = markdown.match(/<\/?(?:script|style|noscript)\b[^>]*>/gi);
      return { pass: !m, detail: m ? `leaked ${m.length} tag(s): ${sample(m)}` : "" };
    },
  },
  {
    name: "no-relative-links",
    severity: "error",
    check: ({ markdown }) => {
      // ](/x  ](./x  ](../x  — but NOT ](//cdn (protocol-relative, resolvable)
      const m = markdown.match(/\]\((?:\/(?!\/)|\.\.?\/)[^)]*\)/g);
      return { pass: !m, detail: m ? `${m.length} relative target(s): ${sample(m)}` : "" };
    },
  },
  {
    name: "no-mangled-links",
    severity: "error",
    check: ({ markdown }) => {
      // a space-less title squashed against the url: ](url"text
      const m = markdown.match(/\]\([^\s)]*"[^\s)]/g);
      return { pass: !m, detail: m ? `${m.length} mangled link(s): ${sample(m)}` : "" };
    },
  },
  {
    name: "non-empty-when-contentful",
    severity: "error",
    check: ({ html, markdown }) => {
      const htmlWords = words(visibleText(html));
      if (htmlWords < CONTENTFUL_HTML_WORDS) return { pass: true };
      const mdWords = words(markdown);
      return {
        pass: mdWords >= MIN_MARKDOWN_WORDS,
        detail: `source ~${htmlWords}w but markdown only ${mdWords}w`,
      };
    },
  },
  {
    name: "no-secret-leak",
    severity: "error",
    check: ({ markdown }) => {
      const hits = SECRET_PATTERNS.filter((p) => p.re.test(markdown)).map((p) => p.name);
      return { pass: hits.length === 0, detail: hits.length ? `matched: ${hits.join(", ")}` : "" };
    },
  },
  {
    name: "no-leaked-chrome-tags",
    severity: "warn",
    check: ({ markdown }) => {
      const m = markdown.match(
        /<\/?(?:nav|header|footer|aside|form|button|input|select|iframe)\b[^>]*>/gi,
      );
      return { pass: !m, detail: m ? `${m.length} chrome tag(s): ${sample(m)}` : "" };
    },
  },
  {
    name: "no-empty-image-src",
    severity: "warn",
    check: ({ markdown }) => {
      // ![alt]()  — usually a srcset-only image that lost its src
      const m = markdown.match(/!\[[^\]]*\]\(\s*\)/g);
      return { pass: !m, detail: m ? `${m.length} image(s) with empty src` : "" };
    },
  },
  {
    name: "no-empty-or-fragment-links",
    severity: "warn",
    check: ({ markdown }) => {
      const empty = markdown.match(/[^!]\]\(\s*\)/g) ?? [];
      const frag = markdown.match(/\]\(#[^)]*\)/g) ?? [];
      const js = markdown.match(/\]\(javascript:/gi) ?? [];
      const total = empty.length + frag.length + js.length;
      return {
        pass: total === 0,
        detail: total
          ? `${empty.length} empty, ${frag.length} fragment, ${js.length} javascript:`
          : "",
      };
    },
  },
  {
    name: "balanced-code-fences",
    severity: "warn",
    check: ({ markdown }) => {
      const fences = (markdown.match(/^```/gm) ?? []).length;
      return { pass: fences % 2 === 0, detail: fences % 2 ? `${fences} fence markers (odd)` : "" };
    },
  },
  {
    name: "no-html-comments",
    severity: "warn",
    check: ({ markdown }) => ({
      pass: !markdown.includes("<!--"),
      detail: markdown.includes("<!--") ? "html comment leaked into markdown" : "",
    }),
  },
  {
    name: "size-ratio-sane",
    severity: "warn",
    check: ({ html, markdown }) => {
      const src = words(visibleText(html));
      if (src < CONTENTFUL_HTML_WORDS) return { pass: true };
      const ratio = words(markdown) / src;
      // Clean extraction is a subset of the page's visible text, so ratio < ~1.
      // ratio > 1.2 means duplication or chrome leaking back in.
      return {
        pass: ratio <= 1.2,
        detail: ratio > 1.2 ? `markdown/source word ratio ${ratio.toFixed(2)}` : "",
      };
    },
  },
];

export const runInvariants = (ctx: InvariantContext, only?: Severity): InvariantResult[] =>
  INVARIANTS.filter((i) => !only || i.severity === only).map((i) => {
    const { pass, detail = "" } = i.check(ctx);
    return { name: i.name, severity: i.severity, pass, detail: pass ? "" : detail };
  });

/**
 * Tier 1 eval report (run on demand, not in the unit-test path):
 *
 *   cd api && npm run eval:report
 *
 * Runs the whole corpus through the real conversion pipeline, times it, applies
 * every invariant, and prints an aggregate the 6 frozen fixtures never give you:
 * per-invariant pass rates, latency distribution, empty-output rate, extractor
 * mix, and the contentful-but-thin / oversized outliers. Writes eval-report.json
 * for trend tracking and exits non-zero if any error-level invariant is violated.
 */

import { writeFileSync } from "node:fs";
import { getDefuddleContent } from "../../readability";
import { CORPUS, loadEntry } from "./corpus";
import { INVARIANTS, runInvariants } from "./invariants";

const words = (s: string): number => s.split(/\s+/).filter(Boolean).length;

const pct = (xs: number[], p: number): number => {
  if (!xs.length) return 0;
  const s = [...xs].sort((a, b) => a - b);
  return Math.round(s[Math.min(s.length - 1, Math.floor((p / 100) * s.length))]);
};

const pad = (s: string | number, n: number): string => String(s).padEnd(n);

type Row = {
  key: string;
  category: string;
  ms: number;
  mdWords: number;
  mdChars: number;
  htmlChars: number;
  extractorType: string;
  errors: string[];
  warns: string[];
};

const main = async () => {
  const rows: Row[] = [];

  for (const entry of CORPUS) {
    const html = loadEntry(entry);
    const t0 = performance.now();
    const result = await getDefuddleContent(html, entry.url);
    const ms = performance.now() - t0;
    const markdown = result.contentMarkdown ?? "";

    const invs = runInvariants({ url: entry.url, html, markdown, result });
    rows.push({
      key: entry.key,
      category: entry.category,
      ms: Math.round(ms),
      mdWords: words(markdown),
      mdChars: markdown.length,
      htmlChars: html.length,
      extractorType: result.extractorType ?? "(none)",
      errors: invs
        .filter((r) => r.severity === "error" && !r.pass)
        .map((r) => `${r.name}: ${r.detail}`),
      warns: invs
        .filter((r) => r.severity === "warn" && !r.pass)
        .map((r) => `${r.name}: ${r.detail}`),
    });
  }

  // ---- per-page table ----
  console.log("\nPER-PAGE\n" + "-".repeat(72));
  console.log(pad("key", 12) + pad("category", 22) + pad("ms", 7) + pad("mdWords", 9) + "flags");
  for (const r of rows) {
    const flags =
      (r.errors.length ? `${r.errors.length}E ` : "") +
        (r.warns.length ? `${r.warns.length}W` : "") || "ok";
    console.log(pad(r.key, 12) + pad(r.category, 22) + pad(r.ms, 7) + pad(r.mdWords, 9) + flags);
  }

  // ---- invariant pass rates ----
  console.log("\nINVARIANTS (pages passing / total)\n" + "-".repeat(72));
  for (const inv of INVARIANTS) {
    const failed = rows.filter((r) =>
      [...r.errors, ...r.warns].some((x) => x.startsWith(inv.name + ":")),
    );
    const passed = rows.length - failed.length;
    const mark = failed.length === 0 ? "✓" : inv.severity === "error" ? "✗" : "!";
    console.log(
      `${mark} ${pad(inv.name, 28)} ${pad(`${passed}/${rows.length}`, 8)} [${inv.severity}]`,
    );
  }

  // ---- aggregates ----
  const lat = rows.map((r) => r.ms);
  const emptyRate = rows.filter((r) => r.mdWords === 0).length / rows.length;
  const extractorMix = rows.reduce<Record<string, number>>((acc, r) => {
    acc[r.extractorType] = (acc[r.extractorType] ?? 0) + 1;
    return acc;
  }, {});
  const totalErrors = rows.reduce((n, r) => n + r.errors.length, 0);
  const totalWarns = rows.reduce((n, r) => n + r.warns.length, 0);

  console.log("\nAGGREGATE\n" + "-".repeat(72));
  console.log(`pages              ${rows.length}`);
  console.log(`latency ms         p50=${pct(lat, 50)} p95=${pct(lat, 95)} max=${Math.max(...lat)}`);
  console.log(`empty-output rate  ${(emptyRate * 100).toFixed(1)}%`);
  console.log(
    `extractor mix      ${Object.entries(extractorMix)
      .map(([k, v]) => `${k}:${v}`)
      .join("  ")}`,
  );
  console.log(`error violations   ${totalErrors}`);
  console.log(`warn violations    ${totalWarns}`);

  const report = {
    generatedFrom: rows.length + " corpus pages",
    aggregate: {
      pages: rows.length,
      latencyMs: { p50: pct(lat, 50), p95: pct(lat, 95), max: Math.max(...lat) },
      emptyOutputRate: emptyRate,
      extractorMix,
      errorViolations: totalErrors,
      warnViolations: totalWarns,
    },
    pages: rows,
  };
  writeFileSync("eval-report.json", JSON.stringify(report, null, 2));
  console.log("\nwrote eval-report.json");

  if (totalErrors > 0) {
    console.error(`\nFAIL: ${totalErrors} error-level invariant violation(s).`);
    process.exit(1);
  }
};

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

# Plugin Development Guide

This guide walks you through developing custom plugins for Steel Browser's extensible architecture.

## 🚀 Quick Start

### Creating Your First Plugin

```typescript
import { BasePlugin, PluginOptions } from '@steel-browser/api/cdp-plugin';
import { Browser, Page } from 'puppeteer-core';

export class HelloWorldPlugin extends BasePlugin {
  constructor(options: PluginOptions) {
    super({ name: 'hello-world', ...options });
  }

  async onBrowserLaunch(browser: Browser): Promise<void> {
    console.log('Hello from the browser launch event!');
  }

  async onPageCreated(page: Page): Promise<void> {
    console.log(`New page created: ${page.url()}`);
  }
}

// Usage
const plugin = new HelloWorldPlugin({});
cdpService.registerPlugin(plugin);
```

## 🏗️ Plugin Architecture

### Base Plugin Class

All plugins extend the `BasePlugin` abstract class:

```typescript
abstract class BasePlugin {
  public name: string;
  protected options: PluginOptions;
  protected cdpService: CDPService | null;

  constructor(options: PluginOptions);
  public setService(service: CDPService): void;

  // Lifecycle hooks (all optional)
  public async onBrowserLaunch(browser: Browser): Promise<void> {}
  public async onPageCreated(page: Page): Promise<void> {}
  public async onPageNavigate(page: Page): Promise<void> {}
  public async onPageUnload(page: Page): Promise<void> {}
  public async onBrowserClose(browser: Browser): Promise<void> {}
  public async onBeforePageClose(page: Page): Promise<void> {}
  public async onShutdown(): Promise<void> {}
}
```

### Plugin Options

```typescript
interface PluginOptions {
  name: string;
  [key: string]: any; // Additional plugin-specific options
}
```

## 🔄 Lifecycle Events

### Event Order

```
1. onBrowserLaunch    - Browser process starts
2. onPageCreated      - New page/tab created
3. onPageNavigate     - Page navigates to URL
4. onPageUnload       - Page unloads/navigates away
5. onBeforePageClose  - Before page closes
6. onBrowserClose     - Browser process closes
7. onShutdown         - Plugin cleanup
```

### Event Details

#### onBrowserLaunch(browser: Browser)
- Called when the browser process starts
- Use for browser-level configuration
- Access to the Browser instance

#### onPageCreated(page: Page)
- Called when a new page/tab is created
- Perfect for page-level setup (request interception, etc.)
- Access to the Page instance

#### onPageNavigate(page: Page)
- Called before page navigation
- Use for URL-based logic or navigation tracking

#### onPageUnload(page: Page)
- Called when page unloads or navigates away
- Cleanup page-specific resources

#### onBeforePageClose(page: Page)
- Called before a page closes
- Last chance for page cleanup

#### onBrowserClose(browser: Browser)
- Called when browser process closes
- Browser-level cleanup

#### onShutdown()
- Called during plugin shutdown
- Final cleanup opportunity

## 📝 Plugin Examples

### 1. Request Logger Plugin

```typescript
export class RequestLoggerPlugin extends BasePlugin {
  private logFile: string;

  constructor(options: PluginOptions & { logFile?: string }) {
    super({ name: 'request-logger', ...options });
    this.logFile = options.logFile || 'requests.log';
  }

  async onPageCreated(page: Page): Promise<void> {
    await page.setRequestInterception(true);

    page.on('request', (request) => {
      const logEntry = {
        timestamp: new Date().toISOString(),
        method: request.method(),
        url: request.url(),
        headers: request.headers()
      };

      // Log to file or console
      console.log('Request:', logEntry);
      request.continue();
    });
  }
}
```

### 2. Ad Blocker Plugin

```typescript
export class AdBlockerPlugin extends BasePlugin {
  private blockedDomains: Set<string>;
  private blockedCount: number = 0;

  constructor(options: PluginOptions & { blockedDomains?: string[] }) {
    super({ name: 'ad-blocker', ...options });
    this.blockedDomains = new Set(options.blockedDomains || [
      'doubleclick.net',
      'googleadservices.com',
      'googlesyndication.com'
    ]);
  }

  async onPageCreated(page: Page): Promise<void> {
    await page.setRequestInterception(true);

    page.on('request', (request) => {
      const url = new URL(request.url());

      if (this.blockedDomains.has(url.hostname)) {
        this.blockedCount++;
        console.log(`Blocked ad request: ${url.hostname}`);
        request.abort();
      } else {
        request.continue();
      }
    });
  }

  async onShutdown(): Promise<void> {
    console.log(`Ad Blocker: Blocked ${this.blockedCount} requests`);
  }
}
```

### 3. Screenshot Plugin

```typescript
export class ScreenshotPlugin extends BasePlugin {
  private screenshotDir: string;

  constructor(options: PluginOptions & { screenshotDir?: string }) {
    super({ name: 'screenshot', ...options });
    this.screenshotDir = options.screenshotDir || './screenshots';
  }

  async onPageNavigate(page: Page): Promise<void> {
    // Take screenshot after navigation
    setTimeout(async () => {
      try {
        const url = new URL(page.url());
        const filename = `${url.hostname}-${Date.now()}.png`;
        const filepath = path.join(this.screenshotDir, filename);

        await page.screenshot({ path: filepath, fullPage: true });
        console.log(`Screenshot saved: ${filepath}`);
      } catch (error) {
        console.error('Screenshot failed:', error);
      }
    }, 2000);
  }
}
```

### 4. Performance Monitor Plugin

```typescript
export class PerformancePlugin extends BasePlugin {
  private metrics: Map<string, any> = new Map();

  constructor(options: PluginOptions) {
    super({ name: 'performance-monitor', ...options });
  }

  async onPageCreated(page: Page): Promise<void> {
    // Enable performance monitoring
    await page.coverage.startJSCoverage();
    await page.coverage.startCSSCoverage();

    page.on('load', async () => {
      const performanceMetrics = await page.evaluate(() => {
        const perfData = performance.getEntriesByType('navigation')[0];
        return {
          domContentLoaded: perfData.domContentLoadedEventEnd - perfData.domContentLoadedEventStart,
          loadComplete: perfData.loadEventEnd - perfData.loadEventStart,
          firstPaint: performance.getEntriesByType('paint')[0]?.startTime || 0
        };
      });

      this.metrics.set(page.url(), performanceMetrics);
      console.log(`Performance metrics for ${page.url()}:`, performanceMetrics);
    });
  }

  async onShutdown(): Promise<void> {
    console.log('Performance Summary:', Object.fromEntries(this.metrics));
  }
}
```

## 🔧 Advanced Plugin Development

### Accessing CDP Service

```typescript
export class AdvancedPlugin extends BasePlugin {
  async onBrowserLaunch(browser: Browser): Promise<void> {
    // Access the CDP service
    if (this.cdpService) {
      // Get all pages
      const pages = await this.cdpService.getPages();

      // Access primary page
      const primaryPage = this.cdpService.primaryPage;

      // Register hooks
